import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%82%B5%E3%83%BC%E3%83%95%E3%82%A3%E3%83%B3.html","title":"サーフィン","lang":"en-US","frontmatter":{},"git":{"createdTime":1707021122000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":10}]},"readingTime":{"minutes":0.82,"words":246},"filePathRelative":"サーフィン.md"}`),a={name:`サーフィン.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="サーフィン" tabindex="-1"><a class="header-anchor" href="#サーフィン"><span>サーフィン</span></a></h1><ul><li>[SurfLog]]</li><li><a href="./パドリング.html">パドリング</a></li><li><a href="./スケーボーでサーフィンの陸トレ.html">スケーボーでサーフィンの陸トレ</a></li><li><a href="./サーファープログラマー.html">サーファープログラマー</a></li><li><a href="./腕時計.html">腕時計</a></li><li><a href="./耳栓.html">耳栓</a></li><li><a href="./サーフボード.html">サーフボード</a></li></ul><h2 id="タッパー-2026-06-29-月" tabindex="-1"><a class="header-anchor" href="#タッパー-2026-06-29-月"><span>タッパー 2026-06-29 (月)</span></a></h2><p>ハーレーのMLのタッパーを買う。かぶるタイプ。2万円の10%オフで1.8万円くらい。</p><p>AVANTAGE PLUS1と書いてある。1mm。</p><h2 id="お着替えポンチョ" tabindex="-1"><a class="header-anchor" href="#お着替えポンチョ"><span>お着替えポンチョ</span></a></h2><p><a href="https://a.r10.to/hRbe4s" target="_blank" rel="noopener noreferrer">楽天: お着替えポンチョ ファイバータオル</a></p><p>2026/5/25に購入。スクーターで鵠沼からの帰りに何か上に羽織るのにいいのが無いかと思って購入。 本来は着替えに使うものだが。</p><h3 id="試してみた-2026-6-16" tabindex="-1"><a class="header-anchor" href="#試してみた-2026-6-16"><span>試してみた 2026/6/16</span></a></h3><p>ヘルメットはフードを被った上からかぶるとヘルメットが汚れないのは嬉しい。 走ると袖などは結構バタつくが、お尻のあたりがびちゃびちゃになったりはしないし、布の部分は意外と風を防ぐのか温かい。 そんなに飛ばさなければいい感じな気がする。</p><p>海パンならこれで足をふいた後にレインコートのズボンだけはいて帰るといいかもしらん。</p><h3 id="かなり良い-2026-06-20" tabindex="-1"><a class="header-anchor" href="#かなり良い-2026-06-20"><span>かなり良い 2026-06-20</span></a></h3><p>もう一度使ってみた。今度は水着とラッシュガードで向こうで着替えるパターン。 かなり良い。</p><p>そんなに分厚くなくてかさばらない割には結構ちゃんと水を吸う。 風をあまり通さないので、帰りに上着代わりにそのまま来て帰る事も出来る。 マルチに使えてかなり良い。</p><p>これはおすすめ。</p><h2 id="ジャーフル" tabindex="-1"><a class="header-anchor" href="#ジャーフル"><span>ジャーフル</span></a></h2><p>国内サイズM、海外サイズSくらいがちょうどいいか。 2025/4/17 オニールの24640円で購入。</p><h2 id="フィン" tabindex="-1"><a class="header-anchor" href="#フィン"><span>フィン</span></a></h2><p>以下のフィンのLを2025-09-23 (火)に4999円で購入。</p><p><a href="https://amzn.to/3VvTfby" target="_blank" rel="noopener noreferrer">amazon: G3/G5/G6 サイズ 3 フィンセット AQUBONA</a></p><p>Mを買おうとしたら何故か10日くらいと出たのでLargeにしてみる。実際そこまでLargeでもデカく無さそうだし、Largeを試してみるのもいいだろう、という気もしたので。</p><p>FCS2を買ったのだが、なぜか写真はFCS2っぽくなくて不安だったけれど届いたものはちゃんとFCS2でした。ものは良さそうに見える。</p><h2 id="記録" tabindex="-1"><a class="header-anchor" href="#記録"><span>記録</span></a></h2><p>たまにサーフィンで進捗などがあった時に書きたくなったら書く所。今後は<a href="./SurfLog.html">SurfLog</a>に。</p><h3 id="_2024-08-05-月" tabindex="-1"><a class="header-anchor" href="#_2024-08-05-月"><span>2024-08-05 (月)</span></a></h3><p>ワガエは今日の17時なら乗れる。潮は134cmくらいらしい。もう20cm浅いと無理か。</p><p>追記: 17:00 107cm, 18:00 128cmで17:20くらいから乗れた。110cm超えてればなんとか、という感じか。</p><h3 id="_2024-06-24-月" tabindex="-1"><a class="header-anchor" href="#_2024-06-24-月"><span>2024-06-24 (月)</span></a></h3><p>今日はショルダーの無い波で、テイクオフから下に降りてボトムターンして一発あてる、が出来た。 ホームポイントはこのショルダーが無いポイントブレイクになる事が結構あって、 そういう時にショルダーに抜けて終わり、というのをなんとかしたいと思っていたのだが、今日はじめていい感じに出来た。</p><p>ただ今日は結構サイズがあってそのせいで出来たという部分もあるので、ムネカタくらいの時にも出来るかは試してみないと分からないな。</p>`,30)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};